<script setup lang="ts">
import MoreIcon from '../components/MoreIcon.vue'
import {ElButton,ElAlert} from 'element-plus'
import 'element-plus/es/components/button/style/css'
import 'element-plus/es/components/alert/style/css'
import { confirmDialog } from '../services/productDialog'
import { computed,onBeforeUnmount,onMounted,ref,watch } from 'vue'
import {readAttachmentAvailability,type AttachmentAvailability} from '../services/attachmentAvailability'
import {clientOwnerScope} from '../services/clientContext'
import { useRouter } from 'vue-router'
import { useAuthStore } from '../stores/auth'
import AttachmentDiagnosticDialog from '../components/AttachmentDiagnosticDialog.vue'
import {diagnosticOpen} from '../services/attachmentDiagnostics'
import AttachmentPreviewDialog from '../components/AttachmentPreviewDialog.vue'
import AttachmentThumbnail from '../components/AttachmentThumbnail.vue'
import { attachmentCacheUsage,attachmentLibrary,attachmentLibrarySummary,deleteAttachment,exportAttachmentArchive,isOfficeAttachment,openAttachmentContent,cachedAttachment,retryLocalAttachment,type AttachmentLibrarySummary,type LibraryAttachment } from '../services/attachments'
const router=useRouter(),auth=useAuthStore(),ownerId=computed(()=>String(auth.user?.userId||''))
const items=ref<LibraryAttachment[]>([]),summary=ref<AttachmentLibrarySummary>({total:0,images:0,audio:0,files:0,orphan:0,totalBytes:0}),cache=ref({total:0,limit:0})
const query=ref(''),type=ref(''),referenceState=ref(''),sort=ref('createdDesc'),page=ref(1),size=30,total=ref(0),hasMore=ref(false),busy=ref(false),error=ref(''),selected=ref(new Set<string>()),selectionMode=ref(false),viewMode=ref<'grid'|'list'>(localStorage.getItem('note-flow-attachment-view')==='list'?'list':'grid'),previewIndex=ref(-1);let searchTimer=0
const availability=ref<Record<string,AttachmentAvailability>>({}),operation=ref(''),actionMessage=ref('');let loadSequence=0,availabilitySequence=0,availabilityTimer=0
const libraryNotice=ref('')
async function refreshLibrary(){page.value=1;await Promise.all([load(),loadSummary()])}
const diagnosticItem=ref<LibraryAttachment>(),failedItem=ref<LibraryAttachment>()
function inspect(item:LibraryAttachment){diagnosticItem.value=item}
const selectedItems=computed(()=>items.value.filter(item=>selected.value.has(item.uid)))
function bytes(value=0){if(value<1024)return`${value} B`;if(value<1024**2)return`${(value/1024).toFixed(1)} KB`;if(value<1024**3)return`${(value/1024**2).toFixed(1)} MB`;return`${(value/1024**3).toFixed(2)} GB`}
function kind(item:LibraryAttachment){return item.role==='image'?'图片':item.role==='audio'?'音频':'文件'}
async function load(){const request=++loadSequence,owner=ownerId.value,scope=clientOwnerScope(owner);busy.value=true;error.value='';libraryNotice.value='';try{const result=await attachmentLibrary({q:query.value||undefined,type:type.value||undefined,referenceState:referenceState.value||undefined,sort:sort.value,page:page.value,size});if(request!==loadSequence||owner!==ownerId.value||scope!==clientOwnerScope(owner))return;const states=await readAttachmentAvailability(owner,result.items).catch(()=>({}));if(request!==loadSequence||owner!==ownerId.value||scope!==clientOwnerScope(owner))return;items.value=result.items;libraryNotice.value=result.notice||'';availability.value=states;total.value=result.total;hasMore.value=result.hasMore;selected.value=new Set([...selected.value].filter(uid=>result.items.some(item=>item.uid===uid)))}catch(source){if(request===loadSequence)error.value=source instanceof Error?source.message:'附件加载失败'}finally{if(request===loadSequence)busy.value=false}}
async function saveOffline(item:LibraryAttachment){const owner=ownerId.value,scope=clientOwnerScope(owner);operation.value=item.uid;error.value='';try{await cachedAttachment(owner,item);if(owner!==ownerId.value||scope!==clientOwnerScope(owner))return;availability.value={...availability.value,...await readAttachmentAvailability(owner,[item])};await loadSummary();if(availability.value[item.uid]?.offline!==true)error.value='附件可读取，但未能保存在本机，请检查缓存空间'}catch{if(owner===ownerId.value&&scope===clientOwnerScope(owner)){error.value='保存到本机失败，请检查附件或网络';failedItem.value=item}}finally{operation.value=''}}
async function retryUpload(item:LibraryAttachment){
 const owner=ownerId.value,scope=clientOwnerScope(owner);if(operation.value)return
 operation.value=item.uid;error.value='';actionMessage.value=''
 try{const states=await readAttachmentAvailability(owner,[item]);if(owner!==ownerId.value||scope!==clientOwnerScope(owner))return;const state=states[item.uid];if(!state?.retryable||!state.localUid)throw Error('本机附件不可用于重试，请先检查附件');await retryLocalAttachment(owner,state.localUid);if(owner!==ownerId.value||scope!==clientOwnerScope(owner))return;await load();if(owner!==ownerId.value||scope!==clientOwnerScope(owner))return;actionMessage.value='已加入重试队列。打开所属内容后继续上传。';locate(item)}catch(source){if(owner===ownerId.value&&scope===clientOwnerScope(owner)){error.value=source instanceof Error?source.message:'重试失败，请检查附件';failedItem.value=item}}finally{if(owner===ownerId.value&&scope===clientOwnerScope(owner))operation.value=''}
}

async function refreshAvailability(){const request=++availabilitySequence,owner=ownerId.value,scope=clientOwnerScope(owner),visible=items.value.slice(),signature=visible.map(item=>item.uid).join('|');try{const states=await readAttachmentAvailability(owner,visible);if(request===availabilitySequence&&owner===ownerId.value&&scope===clientOwnerScope(owner)&&signature===items.value.map(item=>item.uid).join('|'))availability.value=states}catch{/* Keep the last known state; explicit diagnostics can retry. */}}
function cacheChanged(event:Event){if((event as CustomEvent).detail?.scope!==clientOwnerScope(ownerId.value))return;window.clearTimeout(availabilityTimer);availabilityTimer=window.setTimeout(()=>void refreshAvailability(),200)}
async function loadSummary(){const owner=ownerId.value,scope=clientOwnerScope(owner);const [server,local]=await Promise.allSettled([attachmentLibrarySummary(),attachmentCacheUsage(owner)]);if(owner!==ownerId.value||scope!==clientOwnerScope(owner))return;if(server.status==='fulfilled')summary.value=server.value;if(local.status==='fulfilled')cache.value=local.value}
function setType(value:string){if(value==='orphan'){type.value='';referenceState.value='orphan'}else{type.value=value;referenceState.value=''}page.value=1}
function toggle(uid:string,checked:boolean){const next=new Set(selected.value);checked?next.add(uid):next.delete(uid);selected.value=next}
function toggleSelectionMode(){selectionMode.value=!selectionMode.value;if(!selectionMode.value)selected.value=new Set()}
async function open(item:LibraryAttachment){error.value='';try{await diagnosticOpen(ownerId.value,item);cache.value=await attachmentCacheUsage(ownerId.value)}catch(source){failedItem.value=item;error.value=source instanceof Error?source.message:'附件打开失败'}}
function preview(item:LibraryAttachment){if(isOfficeAttachment(item)){void open(item);return}const index=items.value.findIndex(value=>value.uid===item.uid);if(index>=0)previewIndex.value=index}
async function downloadSelected(){if(!selectedItems.value.length)return;busy.value=true;try{await exportAttachmentArchive(selectedItems.value.map(item=>item.uid))}catch(source){error.value=source instanceof Error?source.message:'附件导出失败'}finally{busy.value=false}}
async function removeSelected(){const targets=selectedItems.value.filter(item=>item.referenceCount===0);if(!targets.length||!await confirmDialog(`删除选中的 ${targets.length} 个无引用附件（${bytes(targets.reduce((sum,item)=>sum+item.sizeBytes,0))}）？文件将在保留期后物理回收。`))return;busy.value=true;let failed=0;for(const item of targets)try{await deleteAttachment(item,ownerId.value)}catch{failed++}selected.value=new Set();await Promise.all([load(),loadSummary()]);if(failed)error.value=`${failed} 个附件删除失败，可能已被重新引用`;busy.value=false}
function locate(item:LibraryAttachment){const source=item.references.find(value=>value.noteUid||value.taskUid||value.knowledgeUid||value.cardUid);if(source?.noteUid)router.push({path:'/notes',query:{note:source.noteUid}});else if(source?.taskUid)router.push({path:'/tasks',query:{task:source.taskUid}});else if(source?.knowledgeUid)router.push(`/knowledge/${source.knowledgeUid}`);else if(source?.cardUid)router.push(`/knowledge/cards/${source.cardUid}/edit`)}
watch([type,referenceState,sort],()=>{page.value=1;void load()});watch(query,()=>{window.clearTimeout(searchTimer);searchTimer=window.setTimeout(()=>{page.value=1;void load()},250)});watch(ownerId,()=>{loadSequence++;items.value=[];availability.value={};selected.value=new Set();void load();void loadSummary()})
onBeforeUnmount(()=>{loadSequence++;availabilitySequence++;window.clearTimeout(searchTimer);window.clearTimeout(availabilityTimer);window.removeEventListener('note-flow:attachment-cache-change',cacheChanged)})
watch(viewMode,value=>localStorage.setItem('note-flow-attachment-view',value));onMounted(()=>{window.addEventListener('note-flow:attachment-cache-change',cacheChanged);void load();void loadSummary()})
</script>
<style scoped>
.attachment-library{width:min(var(--pc-standard-width),100%);max-width:none}.attachment-library-head{align-items:center;margin-bottom:10px}.attachment-library-head>div{display:flex;align-items:baseline;gap:10px}.attachment-library-head h1{margin:0}.attachment-library-head p{margin:0}.attachment-summary-line{display:flex;align-items:center;gap:14px;margin-bottom:12px;padding:8px 12px;border:1px solid var(--pc-border);border-radius:9px;background:#fff;color:var(--pc-muted);font-size:9px}.attachment-summary-line b{color:var(--pc-text);font-size:10px}.attachment-summary-line .warning{color:#a96525}.view-switch{display:flex!important;margin-left:0!important;padding:2px;border:1px solid var(--pc-border);border-radius:7px;background:#fff}.view-switch button{width:29px;padding:5px!important}.view-switch button.active{background:var(--pc-primary-soft)!important;color:var(--pc-primary)!important}.attachment-library-grid{grid-template-columns:repeat(auto-fill,minmax(220px,1fr))}.attachment-library-grid>article{grid-template-columns:1fr;padding:0;overflow:hidden}.attachment-library-grid .attachment-select{top:9px;left:9px}.attachment-library-grid .attachment-preview{width:100%;height:144px;border-radius:0}.attachment-library-grid article>div{padding:0 12px}.attachment-library-grid footer{padding:9px 12px 11px}.attachment-library-grid.list{display:grid;grid-template-columns:1fr;gap:0;border:1px solid var(--pc-border);border-radius:10px;background:#fff}.attachment-library-grid.list>article{grid-template-columns:62px minmax(190px,1fr) auto;align-items:center;gap:12px;padding:8px 12px 8px 38px;border:0;border-bottom:1px solid #edf1ee;border-radius:0}.attachment-library-grid.list>article:last-child{border-bottom:0}.attachment-library-grid.list .attachment-preview{width:62px;height:54px;border-radius:7px}.attachment-library-grid.list article>div{padding:0}.attachment-library-grid.list footer{grid-column:auto;padding:0;border:0}.attachment-library-grid.list .attachment-select{top:50%;left:12px;transform:translateY(-50%)}
.attachment-library-head h1 small{color:var(--pc-muted);font-size:12px}.selection-toggle.active{border-color:var(--pc-primary)!important;background:var(--pc-primary-soft)!important;color:var(--pc-primary)}
.attachment-library-grid{grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:13px}.attachment-library-grid>article{position:relative;overflow:visible;transition:border-color .15s,box-shadow .15s,transform .15s}.attachment-library-grid>article:hover{border-color:#b9cec1;box-shadow:0 8px 24px #17362312;transform:translateY(-1px)}.attachment-library-grid .attachment-preview{position:relative;height:180px;border-radius:9px 9px 0 0}.attachment-library-grid .attachment-preview :deep(img){object-fit:contain;background:#f3f5f4}.preview-hint{position:absolute;right:10px;bottom:10px;padding:5px 9px;border-radius:999px;background:#173e2dcc;color:#fff;font-size:8px;opacity:0;transition:.15s}.attachment-library-grid article:hover .preview-hint{opacity:1}.attachment-library-grid article>.attachment-meta{padding:0 40px 12px 12px}.attachment-card-menu{position:absolute;z-index:6;right:8px;bottom:9px}.attachment-card-menu summary{display:grid;width:28px;height:28px;place-items:center;border-radius:7px;color:#78867e;font-size:16px;cursor:pointer;list-style:none}.attachment-card-menu summary::-webkit-details-marker{display:none}.attachment-card-menu summary:hover,.attachment-card-menu[open] summary{background:#edf3ef;color:var(--pc-primary)}.attachment-card-menu nav{position:absolute;z-index:10;right:0;bottom:34px;display:grid;width:145px;padding:5px;border:1px solid var(--pc-border);border-radius:9px;background:#fff;box-shadow:0 14px 38px #10291a2b}.attachment-card-menu nav button{padding:8px 9px;border:0;border-radius:6px;background:#fff;color:#45554c;text-align:left}.attachment-card-menu nav button:hover{background:var(--pc-primary-soft);color:var(--pc-primary)}.attachment-library-grid.list article>.attachment-meta{padding:0 40px 0 0}.attachment-library-grid.list .attachment-card-menu{position:relative;right:auto;bottom:auto}.attachment-library-grid.list .preview-hint{display:none}
.attachment-library{box-sizing:border-box;display:flex;height:calc(100vh - 64px);min-height:0;flex-direction:column;overflow:hidden;padding-bottom:18px}.attachment-library-head,.attachment-summary-line,.attachment-library-toolbar{flex:none}.attachment-results{min-height:0;overflow-x:hidden;overflow-y:auto;padding:1px 8px 30px 1px;scrollbar-gutter:stable}.attachment-results .attachment-library-grid{align-content:start}.attachment-results .attachment-library-error{margin-top:0}.attachment-results .attachment-pagination{position:sticky;bottom:-30px;padding:12px 0;background:linear-gradient(transparent,#f6f8f6 24%,#f6f8f6)}

@media(max-width:1079px){
 :global(.community-responsive .attachment-library){padding:16px;min-width:0}
 :global(.community-responsive .attachment-library-head),:global(.community-responsive .attachment-library-head>div),:global(.community-responsive .attachment-library-actions),:global(.community-responsive .attachment-summary-line),:global(.community-responsive .attachment-library-toolbar){flex-wrap:wrap}
 :global(.community-responsive .attachment-library-head>div){align-items:center}
 :global(.community-responsive .attachment-library-toolbar>label){width:100%;min-width:0}
 :global(.community-responsive .attachment-library-toolbar>nav){display:flex;flex-wrap:wrap;margin-left:0;max-width:100%}
 :global(.community-responsive .attachment-library button),:global(.community-responsive .attachment-library select){min-width:44px;min-height:44px}
 :global(.community-responsive .attachment-library-grid.list>article){grid-template-columns:48px minmax(0,1fr);padding:12px}
 :global(.community-responsive .attachment-library-grid.list footer){grid-column:1/-1;flex-wrap:wrap}
}
</style>
<template><main class="attachment-library page">
  <header class="attachment-library-head"><div><h1>附件 <small>{{summary.total}}</small></h1><p>统一查看图片、音频和文件，并定位它们所属的内容。</p></div><div class="attachment-library-actions"><ElButton :loading="busy" @click="refreshLibrary">刷新列表</ElButton><button class="selection-toggle" :class="{active:selectionMode}" @click="toggleSelectionMode">{{selectionMode?'完成选择':'选择'}}</button><button v-if="selectionMode" :disabled="!selectedItems.length||busy" @click="downloadSelected">导出所选</button><button v-if="selectionMode" class="danger" :disabled="!selectedItems.some(item=>item.referenceCount===0)||busy" @click="removeSelected">删除无引用项</button></div></header>
  <section class="attachment-summary-line"><span>图片 <b>{{summary.images}}</b></span><span>音频 <b>{{summary.audio}}</b></span><span>文件 <b>{{summary.files}}</b></span><span>总计 {{bytes(summary.totalBytes)}}</span><span>本机缓存 {{bytes(cache.total)}}</span><span v-if="summary.orphan" class="warning">{{summary.orphan}} 个无引用</span></section>
  <section class="attachment-library-toolbar"><label>⌕<input v-model="query" placeholder="搜索文件名"/></label><nav><button :class="{active:!type&&!referenceState}" @click="setType('')">全部 {{summary.total}}</button><button :class="{active:type==='image'}" @click="setType('image')">图片 {{summary.images}}</button><button :class="{active:type==='audio'}" @click="setType('audio')">音频 {{summary.audio}}</button><button :class="{active:type==='file'}" @click="setType('file')">文件 {{summary.files}}</button><button v-if="summary.orphan" :class="{active:referenceState==='orphan'}" @click="setType('orphan')">无引用 {{summary.orphan}}</button></nav><select v-model="sort"><option value="createdDesc">最近添加</option><option value="oldest">最早添加</option><option value="sizeDesc">文件最大</option><option value="nameAsc">名称排序</option></select><nav class="view-switch" aria-label="视图模式"><button :class="{active:viewMode==='grid'}" title="网格视图" @click="viewMode='grid'">▦</button><button :class="{active:viewMode==='list'}" title="列表视图" @click="viewMode='list'">☰</button></nav></section>
  <section class="attachment-results"><ElAlert v-if="libraryNotice" :title="libraryNotice" type="warning" :closable="false" show-icon/><p v-if="actionMessage" role="status">{{actionMessage}}</p><p v-if="error" class="attachment-library-error">{{error}} <button v-if="failedItem" @click="inspect(failedItem)">检查附件</button></p><section v-if="items.length" class="attachment-library-grid" :class="viewMode"><article v-for="item in items" :key="item.uid" :class="{selected:selected.has(item.uid)}"><label v-if="selectionMode" class="attachment-select"><input type="checkbox" :checked="selected.has(item.uid)" @change="toggle(item.uid,($event.target as HTMLInputElement).checked)"/></label><button class="attachment-preview" :title="`${isOfficeAttachment(item)?'打开编辑':'预览'} ${item.originalFilename}`" @click="preview(item)"><AttachmentThumbnail :owner-id="ownerId" :item="item"/><span class="preview-hint">{{isOfficeAttachment(item)?'打开编辑':'预览'}}</span></button><div class="attachment-meta"><strong :title="item.originalFilename">{{item.originalFilename}}</strong><small>{{kind(item)}} · {{bytes(item.sizeBytes)}}</small><small class="attachment-local-state" :class="availability[item.uid]?.state" :title="availability[item.uid]?.offline===true?'打开时会进一步校验完整性':'检查附件可查看详细原因'">{{availability[item.uid]?.label||'本机状态待检查'}}</small><small v-if="item.references.length">引用于 {{item.references.length===1?(item.references[0].noteTitle||item.references[0].title||'1 个内容'):`${item.references.length} 个内容`}}</small><small v-else class="orphan">无引用，可以安全清理</small></div><details class="attachment-card-menu"><summary title="更多操作" class="pc-more-trigger" aria-label="更多操作"><MoreIcon/></summary><nav><button v-if="availability[item.uid]?.state==='remote'" :disabled="Boolean(operation)" @click="saveOffline(item)">{{operation===item.uid?'正在保存…':'保存到本机'}}</button><button v-if="availability[item.uid]?.retryable" :disabled="Boolean(operation)" @click="retryUpload(item)">重试上传</button><button @click="inspect(item)">检查附件</button><button @click="preview(item)">{{isOfficeAttachment(item)?'打开编辑':'预览'}}</button><button v-if="!isOfficeAttachment(item)" @click="open(item)">用系统程序打开</button><button v-if="item.references.some(value=>value.noteUid||value.taskUid||value.knowledgeUid||value.cardUid)" @click="locate(item)">定位内容</button><button v-if="selectionMode" @click="toggle(item.uid,!selected.has(item.uid))">{{selected.has(item.uid)?'取消选择':'选择此项'}}</button></nav></details></article></section><p v-else-if="!busy" class="attachment-library-empty">{{query?'没有匹配的附件':'这里还没有附件'}}</p><p v-if="busy" class="attachment-library-empty">正在加载附件…</p><footer v-if="total>size" class="attachment-pagination"><button :disabled="page<=1||busy" @click="page--;load()">上一页</button><span>第 {{page}} 页 · 共 {{total}} 个</span><button :disabled="!hasMore||busy" @click="page++;load()">下一页</button></footer></section><AttachmentDiagnosticDialog v-if="diagnosticItem" :owner-id="ownerId" :item="diagnosticItem" @close="diagnosticItem=undefined"/><AttachmentPreviewDialog v-if="previewIndex>=0" :owner-id="ownerId" :items="items" :index="previewIndex" @change="previewIndex=$event" @close="previewIndex=-1"/>
</main></template>

<style scoped>
.attachment-local-state.available{color:var(--pc-primary)}.attachment-local-state.failed,.attachment-local-state.missing,.attachment-local-state.invalid{color:var(--pc-danger,#a63d35)}
</style>
